extern "C" __declspec(dllexport) int DiscordCreate() //unsigned int version, uintptr_t params, void** result
{
    // v47.76 Retail no longer uses DiscordCreate as an implicit Offline/LAN
    // handoff.  Retail deliberately stays on the native CONNECTING path so we
    // can observe/patch the real online-style startup without first constructing
    // the local frontend.  /offline is the explicit escape hatch.  Preserve the
    // legacy early handoff only for Alpha/S2 where this export may still be used.
    if (g_startupModeChosen.load() &&
        g_startupMode == core_runtime::StartupMode::OfflineLan &&
        (g_activeGameKind == games::GameKind::Alpha ||
         g_activeGameKind == games::GameKind::S2))
        entry_point();

	if (*reinterpret_cast<int*>(t9_addresses::Resolve(g_Addrs.ModuleBase, t9_addresses::Retail.versionMarker)) != 0x70657DE9) {
		SETUP_HOOK(render_hook_original, g_Addrs.dvar_show_over_stack, RENDERER, ("Render hook"));
		// SETUP_HOOK(load_script_original, g_Addrs.dvar_load_script, LOAD_SCRIPT, ("Load Script hook"));
	}

	return 1;
}

