	auto CL_Disconnect = reinterpret_cast<void(*)(int, bool, const char*)>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.CL_Disconnect));
	auto LobbyData_SetMap = reinterpret_cast<void(*)(int, const char *)>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.LobbyData_SetMap));
	auto LobbySession_GetControllingLobbySession = reinterpret_cast<int(*)(int)>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.LobbySession_GetControllingLobbySession));
	auto LobbyHostBots_AddBotsToLobby = reinterpret_cast<void(*)(int, int, bool, int, uintptr_t, int)>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.LobbyHostBots_AddBotsToLobby));

	AllocConsole();
	FILE* Dummy;
	freopen_s(&Dummy, ("CONIN$"), ("r"), stdin);
	freopen_s(&Dummy, ("CONOUT$"), ("w"), stdout);
	freopen_s(&Dummy, ("CONOUT$"), ("w"), stderr);
	puts("ZeusOffline v1.9 for game version 1.26.0.11629285\n");
	puts("Waiting for UI...");
	while ((*reinterpret_cast<char*>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.uiReady)) & 1) == 0) {
		Sleep(150);
	}
	puts("UI arrived!");
	*reinterpret_cast<char*>(t9_addresses::Resolve(mbase, t9_addresses::LegacyRetail126.forceReadyFlag)) = 1;
	Cinematic_StopPlayback(0, true);
	LobbyBase_SetNetworkMode(1);
	Com_SessionMode_SetMode(0);
