// Legacy numpad console removed. Verified runtime actions are exposed through
// the integrated slash-command console in CommandConsoleBackend.inl.
static bool IsReadableCommittedAddress(uintptr_t address)
{
    if (!address)
        return false;

    MEMORY_BASIC_INFORMATION mbi = {};
    if (!VirtualQuery(reinterpret_cast<LPCVOID>(address), &mbi, sizeof(mbi)))
        return false;

    if (mbi.State != MEM_COMMIT || (mbi.Protect & PAGE_GUARD) || mbi.Protect == PAGE_NOACCESS)
        return false;

    const DWORD protection = mbi.Protect & 0xFF;
    return protection == PAGE_READONLY || protection == PAGE_READWRITE ||
        protection == PAGE_WRITECOPY || protection == PAGE_EXECUTE ||
        protection == PAGE_EXECUTE_READ || protection == PAGE_EXECUTE_READWRITE ||
        protection == PAGE_EXECUTE_WRITECOPY;
}

static const char* MemoryProtectionName(DWORD protect)
{
    if (protect & PAGE_GUARD) return "GUARD";
    switch (protect & 0xFF)
    {
    case PAGE_NOACCESS: return "NOACCESS";
    case PAGE_READONLY: return "R";
    case PAGE_READWRITE: return "RW";
    case PAGE_WRITECOPY: return "WC";
    case PAGE_EXECUTE: return "X";
    case PAGE_EXECUTE_READ: return "XR";
    case PAGE_EXECUTE_READWRITE: return "XRW";
    case PAGE_EXECUTE_WRITECOPY: return "XWC";
    default: return "?";
    }
}

static void PrintLiveAddress(const char* name, uintptr_t address)
{
    if (!address)
    {
        printf("[MEMSCAN] %-40s MISSING\n", name);
        return;
    }

    MEMORY_BASIC_INFORMATION mbi = {};
    const bool valid = VirtualQuery(reinterpret_cast<LPCVOID>(address), &mbi, sizeof(mbi)) != 0 &&
        mbi.State == MEM_COMMIT && !(mbi.Protect & PAGE_GUARD) && mbi.Protect != PAGE_NOACCESS;

    runtime_ipc::PublishAddress(name, address, g_Addrs.ModuleBase, valid);
    printf("[MEMSCAN] %-40s %p RVA=0x%llX %s %s\n", name,
        reinterpret_cast<void*>(address),
        static_cast<unsigned long long>(address - g_Addrs.ModuleBase),
        valid ? "VALID" : "INVALID",
        valid ? MemoryProtectionName(mbi.Protect) : "-");
}

static void PrintModuleMemoryMap()
{
    const auto moduleBase = g_Addrs.ModuleBase;
    if (!moduleBase)
        return;

    const auto dos = reinterpret_cast<PIMAGE_DOS_HEADER>(moduleBase);
    const auto nt = reinterpret_cast<PIMAGE_NT_HEADERS>(moduleBase + dos->e_lfanew);
    const uintptr_t moduleEnd = moduleBase + nt->OptionalHeader.SizeOfImage;

    size_t committed = 0;
    size_t executable = 0;
    unsigned int regions = 0;

    puts("[MEMSCAN] -------- module memory map --------");
    for (uintptr_t cursor = moduleBase; cursor < moduleEnd;)
    {
        MEMORY_BASIC_INFORMATION mbi = {};
        if (!VirtualQuery(reinterpret_cast<LPCVOID>(cursor), &mbi, sizeof(mbi)) || !mbi.RegionSize)
            break;

        const uintptr_t regionBase = reinterpret_cast<uintptr_t>(mbi.BaseAddress);
        const uintptr_t regionEnd = regionBase + mbi.RegionSize;
        const uintptr_t clippedEnd = regionEnd < moduleEnd ? regionEnd : moduleEnd;
        const size_t clippedSize = clippedEnd > cursor ? static_cast<size_t>(clippedEnd - cursor) : 0;

        if (mbi.State == MEM_COMMIT)
        {
            committed += clippedSize;
            const DWORD p = mbi.Protect & 0xFF;
            if (p == PAGE_EXECUTE || p == PAGE_EXECUTE_READ || p == PAGE_EXECUTE_READWRITE || p == PAGE_EXECUTE_WRITECOPY)
                executable += clippedSize;
        }

        printf("[MEMSCAN] region %03u RVA=0x%08llX size=0x%08llX state=0x%lX protect=%s\n",
            regions++,
            static_cast<unsigned long long>(cursor - moduleBase),
            static_cast<unsigned long long>(clippedSize),
            static_cast<unsigned long>(mbi.State),
            MemoryProtectionName(mbi.Protect));

        cursor = regionEnd > cursor ? regionEnd : cursor + 0x1000;
    }

    printf("[MEMSCAN] map complete: regions=%u committed=0x%llX executable=0x%llX image=0x%llX\n",
        regions,
        static_cast<unsigned long long>(committed),
        static_cast<unsigned long long>(executable),
        static_cast<unsigned long long>(moduleEnd - moduleBase));
}

static void RefreshMissingLiveOffsets()
{
    const char* main_module = "BlackOpsColdWar.exe";

    if (!g_Addrs.config[1])
    {
        uintptr_t match = find_pattern(main_module, "80 3D ?? ?? ?? ?? ?? 75 58 33 C9 48 89 5C 24 ??");
        if (match)
        {
            g_Addrs.config[1] = match + 7 + *reinterpret_cast<int32_t*>(match + 2);
            PrintLiveAddress("config[1] (newly found)", g_Addrs.config[1]);
        }
    }

    if (!g_Addrs.watermark_font)
    {
        uintptr_t match = find_pattern(main_module, "48 8B 05 ?? ?? ?? ?? 48 8B 5C 24 ?? 48 83 C4 30 5F C3");
        if (match)
        {
            g_Addrs.watermark_font = match + 7 + *reinterpret_cast<int32_t*>(match + 3);
            PrintLiveAddress("watermark_font (newly found)", g_Addrs.watermark_font);
        }
    }

    if (!g_Addrs.ScrPlace_GetViewUIContext)
    {
        uintptr_t match = find_pattern(main_module, "E8 ?? ?? ?? ?? 48 8B D8 48 85 C0 74 ?? 8B D7 48 8B C8 E8 ?? ?? ?? ??");
        if (match)
        {
            g_Addrs.ScrPlace_GetViewUIContext = match + 5 + *reinterpret_cast<int32_t*>(match + 1);
            PrintLiveAddress("ScrPlace_GetViewUIContext (candidate)", g_Addrs.ScrPlace_GetViewUIContext);
        }
    }
}

