static const char* LocalContentPhaseName(unsigned int phase)
{
    switch (phase)
    {
        case 1: return "waiting-runtime";
        case 2: return "lua-dump";
        case 3: return "catalog";
        case 4: return "lua-rank";
        case 5: return "native-quick";
        case 6: return "native-deep";
        case 7: return "complete";
        default: return "idle";
    }
}

template <typename T>
static bool ReadLocalContentValue(uintptr_t address, T& value)
{
    SIZE_T got = 0;
    return address &&
        ReadProcessMemory(
            GetCurrentProcess(),
            reinterpret_cast<const void*>(address),
            &value,
            sizeof(value),
            &got) &&
        got == sizeof(value);
}

static bool ReadLocalContentName(uintptr_t address, std::string& value)
{
    value.clear();
    if (!address || !IsReadableAddress(address))
        return false;

    char text[192]{};
    SIZE_T got = 0;
    if (!ReadProcessMemory(
            GetCurrentProcess(),
            reinterpret_cast<const void*>(address),
            text,
            sizeof(text) - 1,
            &got) ||
        got == 0)
        return false;

    text[(std::min)(got, sizeof(text) - 1)] = '\0';

    size_t length = 0;
    while (length < got && text[length])
    {
        const unsigned char ch = static_cast<unsigned char>(text[length]);
        if (ch < 0x20 || ch > 0x7E)
            return false;
        ++length;
    }

    if (length < 2 || length >= sizeof(text) - 1)
        return false;

    value.assign(text, length);
    return true;
}

static std::string CsvEscapeLocalContent(std::string value)
{
    std::string escaped;
    escaped.reserve(value.size() + 8);
    for (char ch : value)
    {
        if (ch == '"')
            escaped += "\"\"";
        else
            escaped += ch;
    }
    return escaped;
}

static bool IsLocalContentVerbosePool(XAssetType type)
{
    switch (type)
    {
        case ASSET_TYPE_STOREPRODUCT:
        case ASSET_TYPE_STORECATEGORY:
        case ASSET_TYPE_STORECATEGORYLIST:
        case ASSET_TYPE_FIRSTPARTYENTITLEMENT:
        case ASSET_TYPE_FIRSTPARTYENTITLEMENTLIST:
        case ASSET_TYPE_ENTITLEMENT:
        case ASSET_TYPE_ENTITLEMENTLIST:
        case ASSET_TYPE_SKU:
        case ASSET_TYPE_WEAPONCAMO:
        case ASSET_TYPE_CHARACTER:
        case ASSET_TYPE_EXECUTION:
            return true;
        default:
            return false;
    }
}

static unsigned int LocalContentConsoleBudget(XAssetType type, unsigned int populatedHint)
{
    if (type == ASSET_TYPE_LUAFILE || type == ASSET_TYPE_LUAFILEDEBUG)
        return 8;

    if (IsLocalContentVerbosePool(type))
        return populatedHint <= 192 ? populatedHint : 96;

    if (populatedHint <= 64)
        return populatedHint;
    if (populatedHint <= 256)
        return 48;
    return 24;
}


