    static RetailLanNativeTraceProbe* FindRetailLanNativeTraceProbe(uintptr_t address)
    {
        for (auto& probe : g_retailLanNativeTraceProbes)
            if (probe.installed && probe.address == address)
                return &probe;
        return nullptr;
    }

    static unsigned long long RetailLanTraceReadQword(uintptr_t address)
    {
        unsigned long long value = 0;
        SIZE_T got = 0;
        if (!address || !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<const void*>(address),
            &value, sizeof(value), &got) || got != sizeof(value))
            return 0;
        return value;
    }

    static bool RetailLanTraceReadAsciiString(uintptr_t address, char* out, size_t outSize)
    {
        if (!out || outSize < 2)
            return false;
        out[0] = '\0';
        if (!address)
            return false;

        unsigned char bytes[96]{};
        SIZE_T got = 0;
        const SIZE_T wanted = static_cast<SIZE_T>((std::min)(sizeof(bytes), outSize - 1));
        const BOOL ok = ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<const void*>(address),
            bytes, wanted, &got);
        if ((!ok && got < 3) || got < 3)
            return false;

        size_t length = 0;
        size_t alpha = 0;
        while (length < got && length + 1 < outSize)
        {
            const unsigned char c = bytes[length];
            if (!c)
                break;
            if (c < 0x20 || c > 0x7E)
                break;
            out[length] = static_cast<char>(c);
            if (std::isalpha(c))
                ++alpha;
            ++length;
        }
        out[length] = '\0';
        if (length < 3 || alpha < 2)
        {
            out[0] = '\0';
            return false;
        }
        return true;
    }

    static bool RetailLanTraceReadEmbeddedAscii(uintptr_t address, char* out, size_t outSize)
    {
        if (!out || outSize < 8)
            return false;
        out[0] = '\0';
        if (!address)
            return false;

        unsigned char bytes[128]{};
        SIZE_T got = 0;
        const BOOL ok = ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<const void*>(address),
            bytes, sizeof(bytes), &got);
        if ((!ok && got < 4) || got < 4)
            return false;

        size_t bestStart = 0;
        size_t bestLength = 0;
        for (size_t i = 0; i < got; )
        {
            while (i < got && (bytes[i] < 0x20 || bytes[i] > 0x7E))
                ++i;
            const size_t begin = i;
            size_t alpha = 0;
            while (i < got && bytes[i] >= 0x20 && bytes[i] <= 0x7E)
            {
                if (std::isalpha(bytes[i]))
                    ++alpha;
                ++i;
            }
            const size_t length = i - begin;
            if (length >= 4 && alpha >= 3 && length > bestLength)
            {
                bestStart = begin;
                bestLength = length;
            }
        }
        if (!bestLength)
            return false;

        const size_t copyLength = (std::min)(bestLength, outSize - 1);
        memcpy(out, bytes + bestStart, copyLength);
        out[copyLength] = '\0';
        return true;
    }

    static void RetailLanTraceAsciiSummary(uintptr_t address, char* out, size_t outSize)
    {
        if (!out || !outSize)
            return;
        out[0] = '\0';
        if (!address)
            return;

        char temp[128]{};
        if (RetailLanTraceReadAsciiString(address, temp, sizeof(temp)))
        {
            strncpy_s(out, outSize, temp, _TRUNCATE);
            return;
        }

        static const uintptr_t offsets[] = { 0, 8, 0x10, 0x18, 0x20, 0x28, 0x30, 0x38, 0x40, 0x48 };
        for (uintptr_t offset : offsets)
        {
            const uintptr_t pointer = static_cast<uintptr_t>(RetailLanTraceReadQword(address + offset));
            if (!pointer || pointer == address)
                continue;
            if (RetailLanTraceReadAsciiString(pointer, temp, sizeof(temp)))
            {
                _snprintf_s(out, outSize, _TRUNCATE, "*+0x%llX:%s",
                    static_cast<unsigned long long>(offset), temp);
                return;
            }
        }

        if (RetailLanTraceReadEmbeddedAscii(address, temp, sizeof(temp)))
            _snprintf_s(out, outSize, _TRUNCATE, "embedded:%s", temp);
    }

    static uintptr_t RetailLanTraceContainingFunction(uintptr_t address)
    {
        if (!address)
            return 0;
        DWORD64 imageBase = 0;
        RUNTIME_FUNCTION* rf = RtlLookupFunctionEntry(address, &imageBase, nullptr);
        if (!rf || !imageBase)
            return 0;
        return static_cast<uintptr_t>(imageBase + rf->BeginAddress);
    }

    static bool RetailLanTraceContainsInsensitive(const char* haystack, const char* needle)
    {
        if (!haystack || !needle || !*needle)
            return false;
        const size_t needleLength = strlen(needle);
        for (const char* h = haystack; *h; ++h)
        {
            size_t i = 0;
            while (i < needleLength && h[i] &&
                std::tolower(static_cast<unsigned char>(h[i])) ==
                std::tolower(static_cast<unsigned char>(needle[i])))
            {
                ++i;
            }
            if (i == needleLength)
                return true;
        }
        return false;
    }

    static bool RetailLanSqjHighSignalName(const char* name)
    {
        if (!name)
            return false;
        return RetailLanTraceContainsInsensitive(name, "sessionsqj") ||
            RetailLanTraceContainsInsensitive(name, "serverlistinfo") ||
            RetailLanTraceContainsInsensitive(name, "onupdatelobbystatusinfo") ||
            RetailLanTraceContainsInsensitive(name, "ongamelobbyclientdataupdate") ||
            RetailLanTraceContainsInsensitive(name, "gameserverstatus") ||
            RetailLanTraceContainsInsensitive(name, "showinmatchmaking") ||
            RetailLanTraceContainsInsensitive(name, "hostaddress") ||
            RetailLanTraceContainsInsensitive(name, "createsetmodel");
    }

