    static bool RetailLuaResolveKdata64FromRaw(
        const std::string& rawFile,
        unsigned int wantedProto,
        unsigned int encodedD,
        unsigned long long& value,
        unsigned int& kgcOrdinal,
        unsigned int& kgcType)
    {
        value = 0;
        kgcOrdinal = 0;
        kgcType = 0;
        if (rawFile.empty() || !RetailLuaCanonicalDumpName(rawFile.c_str()))
            return false;

        char inputPath[MAX_PATH]{};
        sprintf_s(inputPath, "logs\\lua\\dumped\\raw\\%s", rawFile.c_str());
        std::ifstream input(inputPath, std::ios::binary | std::ios::ate);
        if (!input)
            return false;
        const std::streamoff length = input.tellg();
        if (length <= 5 || length > 64ll * 1024ll * 1024ll)
            return false;
        input.seekg(0, std::ios::beg);
        std::vector<unsigned char> bytes(static_cast<size_t>(length));
        input.read(reinterpret_cast<char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
        if (!input || bytes.size() < 6 || bytes[0] != 0x1B || bytes[1] != 'L' || bytes[2] != 'J')
            return false;

        size_t position = 5;
        unsigned int protoOrdinal = 0;
        while (position < bytes.size())
        {
            unsigned int protoSize = 0;
            if (!RetailLuaReadUleb(bytes, position, bytes.size(), protoSize) || protoSize == 0)
                return false;
            if (position + protoSize > bytes.size())
                return false;

            const size_t protoStart = position;
            const size_t protoEnd = position + protoSize;
            if (position + 4 > protoEnd)
                return false;
            const unsigned int actualNumUv = bytes[protoStart + 3];
            position += 4; // flags, params, frame, upvalue count

            unsigned int numKgc = 0, numKn = 0, numBc = 0;
            if (!RetailLuaReadUleb(bytes, position, protoEnd, numKgc) ||
                !RetailLuaReadUleb(bytes, position, protoEnd, numKn) ||
                !RetailLuaReadUleb(bytes, position, protoEnd, numBc))
                return false;

            const size_t beforeDebug = position;
            unsigned int debugLen = 0, firstLine = 0, numLine = 0;
            bool haveDebugHeader = RetailLuaReadUleb(bytes, position, protoEnd, debugLen);
            if (haveDebugHeader && debugLen)
            {
                haveDebugHeader = RetailLuaReadUleb(bytes, position, protoEnd, firstLine) &&
                    RetailLuaReadUleb(bytes, position, protoEnd, numLine);
            }
            if (!haveDebugHeader)
            {
                position = beforeDebug;
                debugLen = 0;
            }

            const size_t codeStart = position;
            size_t lineInfoStart = protoEnd;
            if (debugLen && debugLen <= protoSize)
                lineInfoStart = protoEnd - debugLen;
            const size_t kgcStart = codeStart + static_cast<size_t>(numBc) * 4u +
                static_cast<size_t>(actualNumUv) * 2u;
            if (kgcStart > lineInfoStart)
            {
                position = protoEnd;
                ++protoOrdinal;
                continue;
            }

            if (protoOrdinal == wantedProto)
            {
                if (encodedD >= numKgc)
                    return false;
                // T9/VM0x82 retains LuaJIT's reverse GC-constant indexing for
                // AD constants: KSTR/GSET in this same proto verify D=1 -> the
                // penultimate KGC entry, D=2 -> the entry before it, etc.
                const unsigned int targetOrdinal = numKgc - 1u - encodedD;
                size_t kgcPos = kgcStart;
                for (unsigned int ordinal = 0; ordinal < numKgc; ++ordinal)
                {
                    unsigned int type = 0;
                    if (!RetailLuaReadUleb(bytes, kgcPos, lineInfoStart, type))
                        return false;

                    if (type == 0u)
                    {
                        if (ordinal == targetOrdinal)
                            return false;
                        continue;
                    }
                    if (type == 1u)
                    {
                        unsigned int arrayCount = 0, hashCount = 0;
                        if (!RetailLuaReadUleb(bytes, kgcPos, lineInfoStart, arrayCount) ||
                            !RetailLuaReadUleb(bytes, kgcPos, lineInfoStart, hashCount))
                            return false;
                        const unsigned long long entries =
                            static_cast<unsigned long long>(arrayCount) +
                            static_cast<unsigned long long>(hashCount) * 2ull;
                        if (entries > (1ull << 20))
                            return false;
                        for (unsigned long long i = 0; i < entries; ++i)
                            if (!RetailLuaSkipKtabValue(bytes, kgcPos, lineInfoStart))
                                return false;
                        if (ordinal == targetOrdinal)
                            return false;
                        continue;
                    }
                    if (type >= 2u && type <= 5u)
                    {
                        unsigned int lo = 0, hi = 0;
                        if (!RetailLuaReadUleb(bytes, kgcPos, lineInfoStart, lo) ||
                            !RetailLuaReadUleb(bytes, kgcPos, lineInfoStart, hi))
                            return false;
                        if (ordinal == targetOrdinal)
                        {
                            value = (static_cast<unsigned long long>(hi) << 32) |
                                static_cast<unsigned long long>(lo);
                            kgcOrdinal = ordinal;
                            kgcType = type;
                            return true;
                        }
                        continue;
                    }

                    const size_t stringLength = static_cast<size_t>(type - 6u);
                    if (kgcPos + stringLength > lineInfoStart)
                        return false;
                    if (ordinal == targetOrdinal)
                        return false;
                    kgcPos += stringLength;
                }
                return false;
            }

            position = protoEnd;
            ++protoOrdinal;
        }
        return false;
    }

    static unsigned long long RetailT9LuaIdentifierHash(const char* text) noexcept
    {
        // T9 identifier constants in this Retail corpus are lowercase FNV-1a64
        // followed by the engine's 32-bit-half packing. Verified against
        // getModel, getModelForController, BaseUtility and IsMultiplayer.
        if (!text || !*text)
            return 0;
        unsigned long long hash = 0xCBF29CE484222325ull;
        for (const unsigned char* p = reinterpret_cast<const unsigned char*>(text); *p; ++p)
        {
            unsigned char c = *p;
            if (c >= 'A' && c <= 'Z')
                c = static_cast<unsigned char>(c - 'A' + 'a');
            hash ^= static_cast<unsigned long long>(c);
            hash *= 0x100000001B3ull;
        }
        return ((hash & 0xFFFFFFFFull) << 32) |
            ((hash >> 32) & 0x7FFFFFFFull);
    }

    static bool RetailLuaResolveKgcStringFromRaw(
        const std::string& rawFile,
        unsigned int wantedProto,
        unsigned int encodedD,
        std::string& value,
        unsigned int& kgcOrdinal)
    {
        value.clear();
        kgcOrdinal = 0;
        if (rawFile.empty() || !RetailLuaCanonicalDumpName(rawFile.c_str()))
            return false;

        char inputPath[MAX_PATH]{};
        sprintf_s(inputPath, "logs\\lua\\dumped\\raw\\%s", rawFile.c_str());
        std::ifstream input(inputPath, std::ios::binary | std::ios::ate);
        if (!input)
            return false;
        const std::streamoff length = input.tellg();
        if (length <= 5 || length > 64ll * 1024ll * 1024ll)
            return false;
        input.seekg(0, std::ios::beg);
        std::vector<unsigned char> bytes(static_cast<size_t>(length));
        input.read(reinterpret_cast<char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
        if (!input || bytes.size() < 6 || bytes[0] != 0x1B || bytes[1] != 'L' || bytes[2] != 'J')
            return false;

        size_t position = 5;
        unsigned int protoOrdinal = 0;
        while (position < bytes.size())
        {
            unsigned int protoSize = 0;
            if (!RetailLuaReadUleb(bytes, position, bytes.size(), protoSize) || protoSize == 0)
                return false;
            if (position + protoSize > bytes.size())
                return false;

            const size_t protoStart = position;
            const size_t protoEnd = position + protoSize;
            if (position + 4 > protoEnd)
                return false;
            const unsigned int actualNumUv = bytes[protoStart + 3];
            position += 4;

            unsigned int numKgc = 0, numKn = 0, numBc = 0;
            if (!RetailLuaReadUleb(bytes, position, protoEnd, numKgc) ||
                !RetailLuaReadUleb(bytes, position, protoEnd, numKn) ||
                !RetailLuaReadUleb(bytes, position, protoEnd, numBc))
                return false;

            const size_t beforeDebug = position;
            unsigned int debugLen = 0, firstLine = 0, numLine = 0;
            bool haveDebugHeader = RetailLuaReadUleb(bytes, position, protoEnd, debugLen);
            if (haveDebugHeader && debugLen)
            {
                haveDebugHeader = RetailLuaReadUleb(bytes, position, protoEnd, firstLine) &&
                    RetailLuaReadUleb(bytes, position, protoEnd, numLine);
            }
            if (!haveDebugHeader)
            {
                position = beforeDebug;
                debugLen = 0;
            }

            const size_t codeStart = position;
            size_t lineInfoStart = protoEnd;
            if (debugLen && debugLen <= protoSize)
                lineInfoStart = protoEnd - debugLen;
            const size_t kgcStart = codeStart + static_cast<size_t>(numBc) * 4u +
                static_cast<size_t>(actualNumUv) * 2u;
            if (kgcStart > lineInfoStart)
            {
                position = protoEnd;
                ++protoOrdinal;
                continue;
            }

            if (protoOrdinal == wantedProto)
            {
                if (encodedD >= numKgc)
                    return false;
                const unsigned int targetOrdinal = numKgc - 1u - encodedD;
                std::vector<std::string> strings;
                if (!RetailLuaParseKgcStrings(bytes, kgcStart, lineInfoStart, numKgc, strings) ||
                    targetOrdinal >= strings.size() || strings[targetOrdinal].empty())
                    return false;
                value = strings[targetOrdinal];
                kgcOrdinal = targetOrdinal;
                return true;
            }

            position = protoEnd;
            ++protoOrdinal;
        }
        return false;
    }

    static bool RetailLuaTextHasKnownProtoShape(
        const char* path,
        const char* headerNeedle,
        const char* const* instructionNeedles,
        size_t instructionNeedleCount,
        bool* sawClientSort = nullptr)
    {
        if (sawClientSort)
            *sawClientSort = false;
        if (!path || !*path || !headerNeedle || !*headerNeedle)
            return false;
        std::ifstream input(path);
        if (!input)
            return false;

        bool header = false;
        std::vector<bool> instructions(instructionNeedleCount, false);
        std::string line;
        while (std::getline(input, line))
        {
            if (!header && line.find(headerNeedle) != std::string::npos)
                header = true;
            if (sawClientSort && !*sawClientSort &&
                LowerAsciiCopy(line).find("clientsort") != std::string::npos)
                *sawClientSort = true;
            for (size_t i = 0; i < instructionNeedleCount; ++i)
            {
                if (!instructions[i] && instructionNeedles[i] && *instructionNeedles[i] &&
                    line.find(instructionNeedles[i]) != std::string::npos)
                    instructions[i] = true;
            }
        }
        if (!header)
            return false;
        for (bool found : instructions)
            if (!found)
                return false;
        return true;
    }

    static bool RetailLuaValidateKnownLine318BaseUtilityOwner(
        std::string& decompiledPath,
        std::string& detail)
    {
        decompiledPath = "logs\\lua\\decompiled\\lua_01667_09ED7C53A2620E2A.decompiled.lua.txt";
        detail.clear();

        static constexpr const char* kRaw = "lua_01667_09ED7C53A2620E2A.luac";
        static const char* const kShape[] = {
            "P18:00000 L319 GSET",
            "P18:00001 L319 KCDATA",
            "P18:00002 L319 TGETS",
            "P18:00003 L319 KCDATA",
            "P18:00004 L319 TGETS",
            "P18:00005 L319 CALLMT"
        };

        bool sawClientSort = false;
        const bool shape = RetailLuaTextHasKnownProtoShape(
            decompiledPath.c_str(),
            "-- proto 18 fileOff=0x2229 bytes=189 flags=0x0 params=1 frame=4 uv=0 kgc=5 kn=1 bc=25 debug=25 firstLine=318 lineSpan=7",
            kShape, _countof(kShape), &sawClientSort);

        std::string cod, engine;
        unsigned int codOrdinal = 0, engineOrdinal = 0;
        unsigned long long baseUtility = 0, isMultiplayer = 0, engineFn = 0;
        unsigned int baseOrdinal = 0, baseType = 0;
        unsigned int isMpOrdinal = 0, isMpType = 0;
        unsigned int engineFnOrdinal = 0, engineFnType = 0;

        const bool rawCod = RetailLuaResolveKgcStringFromRaw(kRaw, 18u, 0u, cod, codOrdinal);
        const bool rawBase = RetailLuaResolveKdata64FromRaw(
            kRaw, 18u, 1u, baseUtility, baseOrdinal, baseType);
        const bool rawIsMp = RetailLuaResolveKdata64FromRaw(
            kRaw, 18u, 2u, isMultiplayer, isMpOrdinal, isMpType);
        const bool rawEngine = RetailLuaResolveKgcStringFromRaw(kRaw, 18u, 3u, engine, engineOrdinal);
        const bool rawEngineFn = RetailLuaResolveKdata64FromRaw(
            kRaw, 18u, 4u, engineFn, engineFnOrdinal, engineFnType);

        const unsigned long long expectedBase = RetailT9LuaIdentifierHash("BaseUtility");
        const unsigned long long expectedIsMp = RetailT9LuaIdentifierHash("IsMultiplayer");
        const bool valid = shape && sawClientSort && rawCod && rawBase && rawIsMp && rawEngine && rawEngineFn &&
            _stricmp(cod.c_str(), "CoD") == 0 &&
            _stricmp(engine.c_str(), "Engine") == 0 &&
            baseUtility == expectedBase && isMultiplayer == expectedIsMp &&
            baseType >= 2u && baseType <= 5u && isMpType >= 2u && isMpType <= 5u;

        char text[640]{};
        _snprintf_s(text, sizeof(text), _TRUNCATE,
            "asset=%s proto=18 firstLine=318 lineSpan=7 shape=%u clientSortFileClue=%u CoD=%u BaseUtility=0x%016llX IsMultiplayer=0x%016llX Engine=%u engineFn=0x%016llX",
            kRaw, shape ? 1u : 0u, sawClientSort ? 1u : 0u,
            rawCod && _stricmp(cod.c_str(), "CoD") == 0 ? 1u : 0u,
            baseUtility, isMultiplayer,
            rawEngine && _stricmp(engine.c_str(), "Engine") == 0 ? 1u : 0u,
            engineFn);
        detail = text;

        g_frontendLine318BaseUtilityOwnerValidated.store(valid);
        if (valid)
        {
            StatusPrintf(
                "[LINE318-OWNER] v47.62 VALIDATED asset=%s proto=18 firstLine=318 lineSpan=7 source=x64:144203daf6ccb428.lua constants=CoD/BaseUtility/IsMultiplayer/Engine rawKGC=YES clientSortFileClue=YES.\n",
                kRaw);
            StatusPrintf(
                "[LINE318-CHAIN] v47.62 CoD -> BaseUtility(0x%016llX) -> IsMultiplayer(0x%016llX) -> CALL; T9 opcode names are structural labels, not assumed stock-Lua semantics.\n",
                baseUtility, isMultiplayer);
            StatusPrintf(
                "[LINE318-ROOT] v47.62 probableNilParent=CoD.BaseUtility confidence=HIGH_STRUCTURAL: the validated chain performs the BaseUtility table lookup before IsMultiplayer and the runtime error is index-of-nil. No Lua table/model was fabricated.\n");
        }
        else
        {
            StatusPrintf(
                "[LINE318-OWNER] v47.62 validation incomplete: %s. Falling back to passive ranked cache mapping; no patch/write is authorized.\n",
                detail.c_str());
        }
        return valid;
    }

