    static unsigned int ScanExistingRetailLanLuaBrowserFocus()
    {
        // LAN-only read of already dumped LuaJIT bytecode.  This does NOT start
        // the Lua dumper; it only mines files already present from a prior/manual
        // dump so the normal release launch stays free of broad Lua scanning.
        // v47.19 retains the printable-string neighborhood around
        // each SessionSQJ/server-list hit so we can see the model/native bridge
        // names adjacent to the result-building code without decompiling again.
        WIN32_FIND_DATAA find{};
        HANDLE handle = FindFirstFileA("logs\\lua\\dumped\\raw\\*.luac", &find);
        if (handle == INVALID_HANDLE_VALUE)
        {
            StatusPrintf("[LAN-LUA] no existing raw Lua dump; skipped without starting a Lua scan.\n");
            return 0;
        }

        static const std::array<const char*, 21> terms = {
            "SessionSQJSearchResults", "SessionSQJRefreshInfo", "OnSessionSQJRefreshInfo",
            "serverListRoot", "Servers", "LANServerBrowserDetails", "RefreshListButton",
            "GetLanSelectMenu", "JoinSystemlink", "JoinSystemLink", "OnJoinSystemlink",
            "hostAddress", "showInMatchmaking", "EventJoinLobby", "SessionSQJJoinInitiate",
            "JoinLobby", "serverStatus", "gameServerStatus",
            "CreateSetModel", "SessionSQJUpdateUIInfo", "SessionSQJClearModels"
        };

        struct Row { int score = 0; std::string source; std::set<std::string> hits; };
        struct ContextRow
        {
            std::string source;
            std::string hit;
            int offset = 0;
            std::string value;
        };
        std::map<std::string, Row> rows;
        std::vector<ContextRow> contexts;
        contexts.reserve(512);
        unsigned int files = 0;
        do
        {
            if (find.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)
                continue;
            char path[MAX_PATH]{};
            sprintf_s(path, "logs\\lua\\dumped\\raw\\%s", find.cFileName);
            std::ifstream input(path, std::ios::binary | std::ios::ate);
            if (!input) continue;
            const std::streamoff length = input.tellg();
            if (length <= 0 || length > 32 * 1024 * 1024) continue;
            input.seekg(0, std::ios::beg);
            std::vector<unsigned char> bytes(static_cast<size_t>(length));
            input.read(reinterpret_cast<char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
            if (!input) continue;
            std::vector<std::string> strings;
            ExtractPrintableLuaStrings(bytes, strings);
            auto& row = rows[find.cFileName];
            row.source = find.cFileName;
            for (size_t stringIndex = 0; stringIndex < strings.size(); ++stringIndex)
            {
                const auto& value = strings[stringIndex];
                for (size_t termIndex = 0; termIndex < terms.size(); ++termIndex)
                {
                    if (value != terms[termIndex])
                        continue;
                    if (row.hits.insert(value).second)
                        row.score += (termIndex <= 3 ? 25 : (termIndex <= 6 ? 18 : 10));

                    if (contexts.size() >= 2000)
                        continue;
                    const size_t begin = stringIndex > 7 ? stringIndex - 7 : 0;
                    const size_t finish = (std::min)(strings.size(), stringIndex + 8);
                    for (size_t neighbor = begin; neighbor < finish && contexts.size() < 2000; ++neighbor)
                    {
                        const auto& nearValue = strings[neighbor];
                        if (nearValue.empty() || nearValue.size() > 180)
                            continue;
                        contexts.push_back({
                            find.cFileName,
                            value,
                            static_cast<int>(neighbor) - static_cast<int>(stringIndex),
                            nearValue
                        });
                    }
                }
            }
            ++files;
        } while (FindNextFileA(handle, &find));
        FindClose(handle);

        std::vector<Row> ranked;
        for (auto& pair : rows)
            if (!pair.second.hits.empty()) ranked.push_back(std::move(pair.second));
        std::sort(ranked.begin(), ranked.end(), [](const Row& a, const Row& b)
        {
            if (a.score != b.score) return a.score > b.score;
            return a.source < b.source;
        });
        std::ofstream out("logs\\debug\\lan_browser_lua_focus.tsv", std::ios::out | std::ios::trunc);
        out << "score\tsource\tdistinct_terms\tterms\n";
        for (size_t i = 0; i < ranked.size(); ++i)
        {
            std::string joined;
            for (const auto& hit : ranked[i].hits)
            {
                if (!joined.empty()) joined += ',';
                joined += hit;
            }
            out << ranked[i].score << '\t' << MenuTsvSafe(ranked[i].source) << '\t'
                << ranked[i].hits.size() << '\t' << MenuTsvSafe(joined) << '\n';
            if (i < 20)
                StatusPrintf("[LAN-LUA] rank=%llu score=%d source=%s terms=%s\n",
                    static_cast<unsigned long long>(i), ranked[i].score, ranked[i].source.c_str(), joined.c_str());
        }
        out.close();

        std::ofstream contextOut("logs\\debug\\lan_browser_lua_context.tsv", std::ios::out | std::ios::trunc);
        contextOut << "source\thit_term\tneighbor_offset\tneighbor_value\n";
        std::set<std::string> printedContext;
        unsigned int printed = 0;
        for (const auto& context : contexts)
        {
            contextOut << MenuTsvSafe(context.source) << '\t'
                << MenuTsvSafe(context.hit) << '\t' << context.offset << '\t'
                << MenuTsvSafe(context.value) << '\n';
            if (printed < 48 && context.offset != 0)
            {
                const std::string key = context.hit + "|" + context.value;
                if (printedContext.insert(key).second)
                {
                    StatusPrintf("[LAN-LUA-CONTEXT] source=%s hit=%s off=%d near=%s\n",
                        context.source.c_str(), context.hit.c_str(), context.offset, context.value.c_str());
                    ++printed;
                }
            }
        }
        contextOut.close();

        StatusPrintf("[LAN-LUA] focused existing-dump scan complete files=%u matchedScripts=%llu contextRows=%llu outputs=logs\\debug\\lan_browser_lua_focus.tsv + lan_browser_lua_context.tsv. No Lua dump was started.\n",
            files, static_cast<unsigned long long>(ranked.size()), static_cast<unsigned long long>(contexts.size()));
        return static_cast<unsigned int>(ranked.size());
    }

