    static bool RetailDevSimpleNameChar(unsigned char c)
    {
        return std::isalnum(c) || c == '_' || c == '-' || c == '.' || c == '/' ||
            c == ':' || c == '+' || c == '?' || c == '$' || c == '@';
    }

    static bool RetailDevLooksLikeCommandName(const std::string& value)
    {
        if (value.size() < 2 || value.size() > 96)
            return false;

        bool hasAlpha = false;
        for (unsigned char c : value)
        {
            if (!RetailDevSimpleNameChar(c))
                return false;
            if (std::isalpha(c))
                hasAlpha = true;
        }
        if (!hasAlpha)
            return false;

        // Paths/assets are useful to the general dump but are poor native command
        // candidates, so keep them out of the command-registration ranking.
        const std::string lower = LowerAsciiCopy(value);
        static const char* const fileSuffixes[] = {
            ".ff", ".fd", ".xpak", ".xsub", ".lua", ".luac", ".csv", ".json",
            ".png", ".dds", ".iwi", ".bk2", ".wav", ".mp3", ".txt", ".cfg"
        };
        for (const char* suffix : fileSuffixes)
        {
            if (lower.size() >= strlen(suffix) &&
                lower.compare(lower.size() - strlen(suffix), strlen(suffix), suffix) == 0)
                return false;
        }
        if (lower.find("http://") == 0 || lower.find("https://") == 0)
            return false;
        return true;
    }

    static bool RetailDevLooksLikeKeybindCommand(const std::string& value)
    {
        if (value.size() < 2 || value.size() > 64)
            return false;
        if (value[0] != '+' && value[0] != '-')
            return false;
        for (size_t i = 1; i < value.size(); ++i)
        {
            const unsigned char c = static_cast<unsigned char>(value[i]);
            if (!(std::isalnum(c) || c == '_' || c == '-'))
                return false;
        }
        return true;
    }

    static bool RetailDevLooksLikeDataModel(const std::string& value)
    {
        const std::string lower = LowerAsciiCopy(value);
        if (lower.find("cg.player.") == 0 || lower.find("lui.") == 0 ||
            lower.find("model.") == 0 || lower.find("huditems.") == 0)
            return true;
        if (value.find('.') != std::string::npos && value.find('/') == std::string::npos &&
            value.find('+') == std::string::npos && value.find('-') == std::string::npos)
            return true;
        return false;
    }

    static bool RetailDevLooksLikeDvarName(const std::string& value)
    {
        if (value.size() < 3 || value.size() > 96 || value.find(' ') != std::string::npos ||
            value.find('/') != std::string::npos || value.find(':') != std::string::npos)
            return false;
        const std::string lower = LowerAsciiCopy(value);
        static const char* const prefixes[] = {
            "r_", "cg_", "cl_", "com_", "ui_", "sv_", "g_", "bg_", "pm_",
            "snd_", "fx_", "scr_", "con_", "lui_", "net_", "party_", "lobby_",
            "live_", "dw_", "fs_", "sys_"
        };
        for (const char* prefix : prefixes)
            if (lower.rfind(prefix, 0) == 0)
                return true;
        return lower == "developer" || lower == "developer_script" ||
            lower == "monkeytoy" || lower == "cheats" || lower == "sv_cheats";
    }

    static bool RetailDevLooksLikeNativeCommand(const std::string& value)
    {
        if (RetailDevLooksLikeKeybindCommand(value))
            return true;
        if (!RetailDevLooksLikeCommandName(value) || RetailDevLooksLikeDataModel(value) ||
            RetailDevLooksLikeDvarName(value))
            return false;

        const std::string lower = LowerAsciiCopy(value);
        static const char* const exact[] = {
            "toggleconsole", "clear", "cmdlist", "dvarlist", "bind", "unbind", "unbindall",
            "exec", "vstr", "echo", "wait", "disconnect", "reconnect", "quit", "map",
            "devmap", "map_restart", "fast_restart", "god", "demigod", "noclip", "ufo",
            "notarget", "give", "take", "kill", "spawn", "loadzone", "openmenu", "closemenu",
            "screenshot", "record", "stoprecord", "con_minicon"
        };
        for (const char* name : exact)
            if (lower == name)
                return true;

        // Real console commands are overwhelmingly token-shaped and lowercase.  This
        // intentionally rejects schema/property names such as LobbyType/HistoryIndex.
        bool hasAlpha = false;
        for (unsigned char c : value)
        {
            if (std::isalpha(c))
            {
                hasAlpha = true;
                if (std::isupper(c))
                    return false;
            }
            else if (!(std::isdigit(c) || c == '_' || c == '-'))
                return false;
        }
        return hasAlpha && value.size() <= 48;
    }

    static bool RetailDevContainsLanToken(const std::string& lower)
    {
        size_t pos = 0;
        while ((pos = lower.find("lan", pos)) != std::string::npos)
        {
            const bool left = pos == 0 || !std::isalnum(static_cast<unsigned char>(lower[pos - 1]));
            const size_t end = pos + 3;
            const bool right = end >= lower.size() || !std::isalnum(static_cast<unsigned char>(lower[end]));
            if (left && right)
                return true;
            pos = end;
        }
        return false;
    }

