static bool IsExecutableAddress(const void* address)
{
    MEMORY_BASIC_INFORMATION mbi{};
    if (!address || !VirtualQuery(address, &mbi, sizeof(mbi)))
        return false;

    const DWORD protect = mbi.Protect & 0xFF;
    const bool executable = protect == PAGE_EXECUTE || protect == PAGE_EXECUTE_READ ||
        protect == PAGE_EXECUTE_READWRITE || protect == PAGE_EXECUTE_WRITECOPY;
    return mbi.State == MEM_COMMIT && executable && !(mbi.Protect & PAGE_GUARD) &&
        !(mbi.Protect & PAGE_NOACCESS);
}

static bool WaitForStableGameImage(DWORD timeoutMs)
{
    const ULONGLONG deadline = GetTickCount64() + timeoutMs;
    DWORD previousSize = 0;
    DWORD stableSamples = 0;

    while (GetTickCount64() < deadline)
    {
        const HMODULE module = GetModuleHandleW(nullptr);
        if (module)
        {
            __try
            {
                const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
                if (dos->e_magic == IMAGE_DOS_SIGNATURE && dos->e_lfanew > 0)
                {
                    const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS*>(
                        reinterpret_cast<const unsigned char*>(module) + dos->e_lfanew);
                    if (nt->Signature == IMAGE_NT_SIGNATURE)
                    {
                        const DWORD imageSize = nt->OptionalHeader.SizeOfImage;
                        const DWORD entryRva = nt->OptionalHeader.AddressOfEntryPoint;
                        const void* entry = reinterpret_cast<const unsigned char*>(module) + entryRva;
                        if (imageSize != 0 && imageSize == previousSize && IsExecutableAddress(entry))
                        {
                            if (++stableSamples >= 6)
                                return true;
                        }
                        else
                        {
                            stableSamples = 0;
                        }
                        previousSize = imageSize;
                    }
                }
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                stableSamples = 0;
            }
        }
        Sleep(250);
    }
    return false;
}

static void InitializeConsoleAndLogging()
{
    // LAN-focus build206: restore the normal interactive/native CMD console.
    // This is the client's command console, not the removed T9 diagnostics window.
    bool consoleAvailable = GetConsoleWindow() != nullptr;

    if (!consoleAvailable && AttachConsole(ATTACH_PARENT_PROCESS))
        consoleAvailable = true;

    if (!consoleAvailable && AllocConsole())
        consoleAvailable = true;

    if (consoleAvailable)
    {
        FILE* stream = nullptr;
        freopen_s(&stream, "CONOUT$", "w", stdout);
        freopen_s(&stream, "CONOUT$", "w", stderr);
        freopen_s(&stream, "CONIN$", "r", stdin);

        // Always own the title, even when attaching to an existing parent console.
        SetConsoleTitleW(L"Revamped Console");

        HANDLE output = GetStdHandle(STD_OUTPUT_HANDLE);
        CONSOLE_SCREEN_BUFFER_INFO consoleInfo{};
        if (output != INVALID_HANDLE_VALUE && GetConsoleScreenBufferInfo(output, &consoleInfo))
        {
            COORD size = consoleInfo.dwSize;
            if (size.Y < 12000)
                size.Y = 12000;
            SetConsoleScreenBufferSize(output, size);

            const WORD oldColor = consoleInfo.wAttributes;
            SetConsoleTextAttribute(output, FOREGROUND_GREEN | FOREGROUND_BLUE | FOREGROUND_INTENSITY);
            fputs("\n============================================================\n", stdout);
            fputs("                       COD REVAMPED\n", stdout);
            fputs("============================================================\n", stdout);
            SetConsoleTextAttribute(output, oldColor);
            fflush(stdout);
        }
    }

    if (!StartConsoleFileLogging() && consoleAvailable)
        puts("[LOGGER] Failed to create the diagnostic log file.");
}

// Keep SEH in a leaf function with no C++ objects that require destruction.
// MSVC rejects __try in VersionProxyBootstrapThread because that function owns
// objects such as utils::nt::library.
__declspec(noinline) static DWORD RunRetailEntryPointGuarded() noexcept
{
    DWORD exceptionCode = 0;

    // v47.95: restore the automatic Retail Offline/LAN handoff. v47.76-v47.94
    // held native CONNECTING while also waiting for ui/session values that the
    // missing handoff itself creates. With public services blocked that is a
    // circular wait. entry_point() now waits only for address safety.
    if (g_activeGameKind == games::GameKind::Retail)
    {
        RecordStartupStageInternal(
            "retail-offline-auto-handoff",
            "automatic Offline/LAN frontend handoff restored; s_inited observer-only");
        StatusPrintf(
            "[OFFLINE-BOOT] v47.95 automatic Offline/LAN handoff ENABLED. "
            "s_inited/ui/session values do not gate startup.\n");
        __try
        {
            entry_point();
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            exceptionCode = GetExceptionCode();
            called_once = false;
            is_script_ready = false;
            StatusPrintf(
                "[OFFLINE-BOOT] guarded automatic handoff faulted code=0x%08lX; "
                "startup latch released so /offline or focused retry can run again.\n",
                static_cast<unsigned long>(exceptionCode));
        }
        return exceptionCode;
    }

    if (core_runtime::IsOnlineResearchMode())
    {
        RecordStartupStageInternal(
            "online-research-director-route-wait",
            "offline forcing disabled; waiting for frontend before SetScreen(10)");

        __try
        {
            StatusPrintf(
                "[FRONTEND] Online Research: waiting for native frontend readiness...\n");

            if (!WaitForRetailFrontendReady())
            {
                RecordStartupStageInternal(
                    "online-research-director-route-timeout",
                    "native ui/session readiness timed out");
                return 0;
            }

            StatusPrintf(
                "[FRONTEND] Online Research: frontend ready. "
                "Requesting top-level director screen 10 WITHOUT LAN forcing.\n");

            if (g_Addrs.SetScreen)
            {
                SetScreen(10, 0);
                RecordStartupStageInternal(
                    "online-research-director-route-screen10",
                    "SetScreen(10,0) requested; network mode untouched");
            }
            else
            {
                RecordStartupStageInternal(
                    "online-research-director-route-missing-setscreen",
                    "SetScreen unresolved");
            }
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            exceptionCode = GetExceptionCode();
            RecordStartupStageInternal(
                "online-research-director-route-fault",
                "guarded SetScreen(10) route faulted");
        }

        return exceptionCode;
    }

    __try
    {
        entry_point();
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        exceptionCode = GetExceptionCode();
    }
    return exceptionCode;
}



