    static bool HybridOnlineDvarRelevant(const std::string& name)
    {
        std::string lower = name;
        std::transform(
            lower.begin(), lower.end(), lower.begin(),
            [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

        static const char* kTerms[] =
        {
            "online", "xblive", "lobby", "party", "matchmak", "playlist",
            "network", "join", "host", "server", "session", "steam",
            "invite", "presence", "controller", "xuid",
            "store", "catalog", "inventory", "unlock", "entitlement",
            "operator", "outfit", "blueprint", "camo", "execution",
            "cod_account", "battlenet"
        };

        for (const char* term : kTerms)
            if (lower.find(term) != std::string::npos)
                return true;
        return false;
    }

    static void DumpHybridOnlineDvarSnapshot(const char* label)
    {
        t9_dvars::Refresh();
        const auto entries = t9_dvars::Entries({}, true);

        log_paths::EnsureAll();
        CreateDirectoryA("logs\\online", nullptr);

        char path[MAX_PATH]{};
        sprintf_s(
            path,
            "logs\\online\\hybrid_online_dvars_%lu.csv",
            static_cast<unsigned long>(GetCurrentProcessId()));

        std::ofstream out(path, std::ios::app);
        if (out && out.tellp() == 0)
            out << "label,name,type,flags,value,address\n";

        unsigned int matched = 0;
        unsigned int shown = 0;
        constexpr unsigned int kConsoleLimit = 80;

        for (const auto& entry : entries)
        {
            if (!entry.verified || !HybridOnlineDvarRelevant(entry.name))
                continue;

            ++matched;
            if (out)
            {
                out << '"' << label << "\",\"" << entry.name << "\",\""
                    << entry.type << "\",0x" << std::hex << std::uppercase
                    << entry.flags << std::dec << ",\"" << entry.value
                    << "\",0x" << std::hex << std::uppercase
                    << static_cast<unsigned long long>(entry.address)
                    << std::dec << "\n";
            }

            if (shown < kConsoleLimit)
            {
                StatusPrintf(
                    "[HYBRID-DVAR] %s %s=%s type=%s flags=0x%X addr=0x%llX\n",
                    label,
                    entry.name.c_str(),
                    entry.value.c_str(),
                    entry.type.c_str(),
                    entry.flags,
                    static_cast<unsigned long long>(entry.address));
                ++shown;
            }
        }

        StatusPrintf(
            "[HYBRID-DVAR] %s verifiedRelevant=%u shown=%u%s\n",
            label,
            matched,
            shown,
            matched > shown ? " (full snapshot saved to logs\\online\\hybrid_online_dvars_<pid>.csv)" : "");
    }

    struct HybridRelevantDvarValue
    {
        std::string value;
        std::string type;
        unsigned int flags = 0;
        uintptr_t address = 0;
    };

    using HybridRelevantDvarSnapshot = std::map<std::string, HybridRelevantDvarValue>;

    static HybridRelevantDvarSnapshot CaptureHybridRelevantDvars()
    {
        HybridRelevantDvarSnapshot snapshot;
        t9_dvars::Refresh();
        const auto entries = t9_dvars::Entries({}, true);
        for (const auto& entry : entries)
        {
            if (!entry.verified || !HybridOnlineDvarRelevant(entry.name))
                continue;
            HybridRelevantDvarValue row{};
            row.value = entry.value;
            row.type = entry.type;
            row.flags = entry.flags;
            row.address = entry.address;
            snapshot[entry.name] = std::move(row);
        }
        return snapshot;
    }

    static void LogHybridRelevantDvarDiff(
        const HybridRelevantDvarSnapshot& before,
        const HybridRelevantDvarSnapshot& after,
        const char* label)
    {
        log_paths::EnsureAll();
        CreateDirectoryA("logs\\online", nullptr);
        char path[MAX_PATH]{};
        sprintf_s(path, "logs\\online\\hybrid_frontend_dvar_diff_%lu.tsv",
            static_cast<unsigned long>(GetCurrentProcessId()));
        std::ofstream out(path, std::ios::app);
        if (out && out.tellp() == 0)
            out << "label\tname\tbefore\tafter\ttype\tflags\taddress\n";

        unsigned int changes = 0;
        unsigned int printed = 0;
        std::set<std::string> names;
        for (const auto& item : before) names.insert(item.first);
        for (const auto& item : after) names.insert(item.first);

        for (const auto& name : names)
        {
            const auto b = before.find(name);
            const auto a = after.find(name);
            const std::string beforeValue = b == before.end() ? "<missing>" : b->second.value;
            const std::string afterValue = a == after.end() ? "<missing>" : a->second.value;
            if (beforeValue == afterValue)
                continue;

            ++changes;
            const HybridRelevantDvarValue* meta = a != after.end() ? &a->second : (b != before.end() ? &b->second : nullptr);
            if (out)
            {
                out << (label ? label : "transition") << '\t'
                    << name << '\t' << beforeValue << '\t' << afterValue << '\t'
                    << (meta ? meta->type : "") << '\t'
                    << "0x" << std::hex << std::uppercase << (meta ? meta->flags : 0) << '\t'
                    << "0x" << static_cast<unsigned long long>(meta ? meta->address : 0)
                    << std::dec << "\n";
            }
            if (printed < 40)
            {
                StatusPrintf("[FRONTEND-DVAR] %s %s: %s -> %s\n",
                    label ? label : "transition", name.c_str(),
                    beforeValue.c_str(), afterValue.c_str());
                ++printed;
            }
        }

        StatusPrintf("[FRONTEND-DVAR] %s changes=%u%s\n",
            label ? label : "transition", changes,
            changes > printed ? " (full diff saved to logs\\online\\hybrid_frontend_dvar_diff_<pid>.tsv)" : "");
    }

    // v47.7: the last two runs proved that the richer MP/ZM blades are keyed to
    // LIVE network/session semantics. Returning networkMode to LAN immediately
    // collapses the frontend back to 0x1/0x1011. Keep the frontend LIVE while
    // the public COD/Demonware network blocker remains active, and repair the
    // missing local lobby/member pieces separately. Gameplay still returns to
    // the proven LAN state before the observer exits.
    static std::atomic_bool g_hybridLocalReadyLatch{ false };
    static std::atomic_uint g_hybridReadyRepairCount{ 0 };
    static std::atomic_bool g_hybridFenceReported{ false };
    static std::atomic_bool g_hybridHoldLiveFrontend{ false };
    // v47.83: one-shot native online-menu transition experiment. /mp or /zm
    // arms this only after the dynamically-resolved LIVE frontend is stable.
    // The first natural SetScreen(1) request is allowed to execute unchanged;
    // later requests return to the existing safe fence until we know the result.
    // v47.85: SetScreen(1) is the native Connecting screen on Retail.  The
    // one-shot pass-through experiment proved the game simply asks for that
    // return again, so keep it fenced and report only the first request.
    static std::atomic_bool g_frontendAllowNativeScreen1Once{ false };
    static std::atomic_bool g_frontendReturnToConnectingReported{ false };
    // Non-Retail compatibility path: keep Alpha/S2/Beta on the v47.6
    // bootstrap-then-LAN behavior. v47.7 persistent LIVE is Retail-only.
    static std::atomic_bool g_hybridPreserveLanFrontendCompat{ false };

    // v47.28 isolated frontend-fence guard.  The isolated 0x1020/0x1021
    // frontend is already usable; the bad path is the later service/Connecting
    // transition reached by hover/click.  Block the director's SetScreen(1)
    // request while /mp or /zm owns the isolated frontend and remember its exact
    // caller/owner.  A 10 ms packed-session fallback restores 0x102x if another
    // path changes the state before the director call is made.
    static std::atomic_uint g_hybridLastGoodPackedSession{ 0 };
    static std::atomic_uint g_hybridFenceSnapCount{ 0 };
    static std::atomic_uint64_t g_hybridFenceLastCaller{ 0 };
    static std::atomic_uint64_t g_hybridFenceLastOwner{ 0 };
    static std::atomic_uint64_t g_hybridFenceLastBlockTick{ 0 };

