    void InstallMultiInstanceCompatEarly()
    {
        // Retail must be allowed to complete Steam's normal launcher handoff.
        // In particular, never intercept/suppress ExitProcess for Cold War.
        if (g_activeGameKind == games::GameKind::Retail)
        {
            g_multiInstanceHooksInstalled.store(false);
            return;
        }
        if (g_multiInstanceHooksInstalled.exchange(true))
            return;

        const MH_STATUS init = MH_Initialize();
        if (init != MH_OK && init != MH_ERROR_ALREADY_INITIALIZED)
        {
            g_multiInstanceHooksInstalled.store(false);
            return;
        }

        int created = 0;
        auto hookKernel = [&](const char* name, LPVOID detour, LPVOID* original)
        {
            const MH_STATUS status =
                MH_CreateHookApi(L"kernel32.dll", name, detour, original);
            if (status == MH_OK || status == MH_ERROR_ALREADY_CREATED)
            {
                ++created;
                return true;
            }
            return false;
        };

        hookKernel("CreateMutexA",
            reinterpret_cast<LPVOID>(&CreateMutexAMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateMutexA));
        hookKernel("CreateMutexW",
            reinterpret_cast<LPVOID>(&CreateMutexWMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateMutexW));
        hookKernel("CreateMutexExA",
            reinterpret_cast<LPVOID>(&CreateMutexExAMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateMutexExA));
        hookKernel("CreateMutexExW",
            reinterpret_cast<LPVOID>(&CreateMutexExWMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateMutexExW));
        hookKernel("CreateEventA",
            reinterpret_cast<LPVOID>(&CreateEventAMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateEventA));
        hookKernel("CreateEventW",
            reinterpret_cast<LPVOID>(&CreateEventWMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateEventW));
        hookKernel("CreateSemaphoreA",
            reinterpret_cast<LPVOID>(&CreateSemaphoreAMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateSemaphoreA));
        hookKernel("CreateSemaphoreW",
            reinterpret_cast<LPVOID>(&CreateSemaphoreWMultiDetour),
            reinterpret_cast<LPVOID*>(&g_originalCreateSemaphoreW));
        hookKernel("ExitProcess",
            reinterpret_cast<LPVOID>(&ExitProcessObserveDetour),
            reinterpret_cast<LPVOID*>(&g_originalExitProcess));
        hookKernel("TerminateProcess",
            reinterpret_cast<LPVOID>(&TerminateProcessObserveDetour),
            reinterpret_cast<LPVOID*>(&g_originalTerminateProcess));
        hookKernel("FreeLibraryAndExitThread",
            reinterpret_cast<LPVOID>(&FreeLibraryAndExitThreadObserveDetour),
            reinterpret_cast<LPVOID*>(&g_originalFreeLibraryAndExitThread));

        const MH_STATUS enabled = MH_EnableHook(MH_ALL_HOOKS);
        if (enabled != MH_OK && enabled != MH_ERROR_ENABLED)
            g_multiInstanceHooksInstalled.store(false);

        // Console may not exist yet. A status line with bypass count is printed
        // later from normal initialization.
    }

