namespace
{
    static bool IsReadableProtection(DWORD protect)
    {
        if (protect & (PAGE_GUARD | PAGE_NOACCESS)) return false;
        const DWORD base = protect & 0xFF;
        return base == PAGE_READONLY || base == PAGE_READWRITE || base == PAGE_WRITECOPY ||
            base == PAGE_EXECUTE_READ || base == PAGE_EXECUTE_READWRITE || base == PAGE_EXECUTE_WRITECOPY;
    }

    static std::vector<int> ParsePatternBytes(const char* pattern)
    {
        std::vector<int> bytes;
        if (!pattern) return bytes;
        const char* cursor = pattern;
        while (*cursor)
        {
            while (*cursor == ' ') ++cursor;
            if (!*cursor) break;
            if (*cursor == '?')
            {
                ++cursor;
                if (*cursor == '?') ++cursor;
                bytes.push_back(-1);
            }
            else
            {
                char* next = nullptr;
                const unsigned long value = strtoul(cursor, &next, 16);
                if (next == cursor) return {};
                bytes.push_back(static_cast<int>(value & 0xFF));
                cursor = next;
            }
            while (*cursor == ' ') ++cursor;
        }
        return bytes;
    }

    static uintptr_t FindPatternInModule(uintptr_t requestedStart, const char* moduleName, const char* pattern)
    {
        const HMODULE module = GetModuleHandleA(moduleName);
        if (!module) return 0;

        const uintptr_t moduleBase = reinterpret_cast<uintptr_t>(module);
        IMAGE_DOS_HEADER dos{};
        SIZE_T read = 0;
        if (!ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(moduleBase), &dos, sizeof(dos), &read) ||
            read != sizeof(dos) || dos.e_magic != IMAGE_DOS_SIGNATURE || dos.e_lfanew <= 0)
            return 0;

        IMAGE_NT_HEADERS64 nt{};
        if (!ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(moduleBase + dos.e_lfanew), &nt, sizeof(nt), &read) ||
            read != sizeof(nt) || nt.Signature != IMAGE_NT_SIGNATURE || nt.OptionalHeader.SizeOfImage == 0)
            return 0;

        const uintptr_t moduleEnd = moduleBase + nt.OptionalHeader.SizeOfImage;
        uintptr_t cursor = (std::max)(requestedStart, moduleBase);
        if (cursor >= moduleEnd) return 0;

        const std::vector<int> sig = ParsePatternBytes(pattern);
        if (sig.empty()) return 0;

        while (cursor < moduleEnd)
        {
            MEMORY_BASIC_INFORMATION mbi{};
            if (!VirtualQuery(reinterpret_cast<void*>(cursor), &mbi, sizeof(mbi)) || mbi.RegionSize == 0)
                break;

            const uintptr_t regionBase = (std::max)(cursor, reinterpret_cast<uintptr_t>(mbi.BaseAddress));
            const uintptr_t rawRegionEnd = reinterpret_cast<uintptr_t>(mbi.BaseAddress) + mbi.RegionSize;
            const uintptr_t regionEnd = (std::min)(rawRegionEnd, moduleEnd);

            if (mbi.State == MEM_COMMIT && IsReadableProtection(mbi.Protect) && regionEnd > regionBase &&
                static_cast<size_t>(regionEnd - regionBase) >= sig.size())
            {
                std::vector<unsigned char> buffer(static_cast<size_t>(regionEnd - regionBase));
                SIZE_T bytesRead = 0;
                if (ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(regionBase), buffer.data(), buffer.size(), &bytesRead) &&
                    bytesRead >= sig.size())
                {
                    const size_t limit = bytesRead - sig.size();
                    for (size_t i = 0; i <= limit; ++i)
                    {
                        bool match = true;
                        for (size_t j = 0; j < sig.size(); ++j)
                        {
                            if (sig[j] >= 0 && buffer[i + j] != static_cast<unsigned char>(sig[j]))
                            {
                                match = false;
                                break;
                            }
                        }
                        if (match) return regionBase + i;
                    }
                }
            }

            if (rawRegionEnd <= cursor) break;
            cursor = rawRegionEnd;
        }
        return 0;
    }
}

uintptr_t find_pattern(const char* module_name, const char* pattern) {
    return FindPatternInModule(reinterpret_cast<uintptr_t>(GetModuleHandleA(module_name)), module_name, pattern);
}

uintptr_t find_pattern(uintptr_t start, const char* module_name, const char* pattern) {
    return FindPatternInModule(start, module_name, pattern);
}

uintptr_t find_pattern(const char* pattern) {
	const char* pattern_current = pattern;
	uintptr_t current_match = NULL;

	MEMORY_BASIC_INFORMATION64 page_information = {};
	for (auto current_page = reinterpret_cast<unsigned char*>(0); current_page < (unsigned char*)0x00007FFAFFFFFFFF; current_page = reinterpret_cast<unsigned char*>(page_information.BaseAddress + page_information.RegionSize))
	{
		VirtualQuery(reinterpret_cast<LPCVOID>(current_page), reinterpret_cast<PMEMORY_BASIC_INFORMATION>(&page_information), sizeof(MEMORY_BASIC_INFORMATION));
		if (page_information.Protect == PAGE_NOACCESS)
			continue;

		if (page_information.State != MEM_COMMIT)
			continue;

		if (page_information.Protect & PAGE_GUARD)
			continue;

		for (auto current_address = reinterpret_cast<unsigned char*>(page_information.BaseAddress); current_address < reinterpret_cast<unsigned char*>(page_information.BaseAddress + page_information.RegionSize - 0x8); current_address++)
		{
			if (*current_address != GET_BYTE(pattern_current) && *pattern_current != '\?') {
				current_match = 0ULL;
				pattern_current = pattern;
				continue;
			}

			if (!current_match)
				current_match = reinterpret_cast<uintptr_t>(current_address);

			pattern_current += 3;
			if (pattern_current[-1] == NULL)
				return current_match;
		}
	}
	return 0;
}

uintptr_t find_pattern(uintptr_t start, const char* pattern) {
	const char* pattern_current = pattern;
	uintptr_t current_match = NULL;

	MEMORY_BASIC_INFORMATION64 page_information = {};
	for (auto current_page = reinterpret_cast<unsigned char*>(start); current_page < (unsigned char*)0x00007FFAFFFFFFFF; current_page = reinterpret_cast<unsigned char*>(page_information.BaseAddress + page_information.RegionSize))
	{
		VirtualQuery(reinterpret_cast<LPCVOID>(current_page), reinterpret_cast<PMEMORY_BASIC_INFORMATION>(&page_information), sizeof(MEMORY_BASIC_INFORMATION));
		if (page_information.Protect == PAGE_NOACCESS)
			continue;

		if (page_information.State != MEM_COMMIT)
			continue;

		if (page_information.Protect & PAGE_GUARD)
			continue;


		for (auto current_address = current_page; current_address < reinterpret_cast<unsigned char*>(page_information.BaseAddress + page_information.RegionSize - 0x8); current_address++)
		{
			if (*current_address != GET_BYTE(pattern_current) && *pattern_current != '\?') {
				current_match = 0ULL;
				pattern_current = pattern;
				continue;
			}

			if (!current_match)
				current_match = reinterpret_cast<uintptr_t>(current_address);

			pattern_current += 3;
			if (pattern_current[-1] == NULL)
				return current_match;
		}
	}
	return 0;
}

std::pair<void**, void*> patch_import(const std::string& lib, const std::string& func, void* function)
{
	static const utils::nt::library game{};

	const auto game_entry = game.get_iat_entry(lib, func);
	if (!game_entry)
	{
		throw std::runtime_error("Import '" + func + "' not found!");
	}

	const auto original_import = game_entry;
	utils::hook::set(game_entry, function);
	return { game_entry, original_import };
}

